"""PCAP Sentinel web controller (provided - students do not edit this file).

Flow:  upload -> read_pcap -> analyze_traffic -> enrich_context -> run_rules -> build_report -> JSON
New detection rules are picked up automatically from engine/default_rules/.
"""
import logging
import os
import tempfile
from pathlib import Path

from flask import Flask, jsonify, render_template, request
from werkzeug.utils import secure_filename

from engine.ddos_rule import DDoSDetectionRule
from engine.default_rules import enrich_context, load_default_rules, run_rules
from engine.default_rules.capture_files import PcapFormatError
from engine.pcap_reader import read_pcap
from engine.report_builder import build_report
from engine.traffic_analyzer import analyze_traffic

# ---- Tuning knobs -------------------------------------------------------------------------
# Override any rule threshold here: {"<rule_id>": {"<parameter>": value}} (each rule lists its parameters in `defaults`).
RULE_OVERRIDES = {}
# Override analyser settings, e.g. {"rate_window_seconds": 5}.
ANALYZER_CONFIG = {}
MAX_UPLOAD_MB = 25
ALLOWED_EXTENSIONS = {".pcap", ".pcapng"}
# -------------------------------------------------------------------------------------------

logging.basicConfig(level=logging.INFO)
app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = MAX_UPLOAD_MB * 1024 * 1024


def analyze_capture(file_path, filename=None, rule_overrides=None, analyzer_config=None):
    """Run the whole pipeline on one capture file and return the report dictionary."""
    overrides = RULE_OVERRIDES if rule_overrides is None else rule_overrides
    packets, capture_info = read_pcap(file_path)
    context = analyze_traffic(packets, capture_info, analyzer_config or ANALYZER_CONFIG)
    enrich_context(context)
    rules = load_default_rules(overrides)
    rules.append(DDoSDetectionRule(**overrides.get(DDoSDetectionRule.rule_id, {})))
    findings = run_rules(context, rules)
    report = build_report(context, findings)
    report["capture"]["filename"] = filename
    return report


@app.get("/")
def index():
    return render_template("index.html")


@app.post("/api/analyze")
def analyze():
    uploaded = request.files.get("file")
    if uploaded is None or not uploaded.filename:
        return jsonify({"error": "Choose a .pcap or .pcapng file first."}), 400
    filename = secure_filename(uploaded.filename) or "capture"
    extension = Path(filename).suffix.lower()
    if extension not in ALLOWED_EXTENSIONS:
        return jsonify({"error": "Only .pcap and .pcapng files are supported."}), 400
    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(suffix=extension, delete=False) as tmp:   # created with owner-only permissions
            temp_path = tmp.name
            uploaded.save(tmp)
        return jsonify(analyze_capture(temp_path, filename))
    except PcapFormatError as exc:
        return jsonify({"error": f"This is not a readable capture: {exc}"}), 400
    except Exception:
        app.logger.exception("Capture analysis failed")
        return jsonify({"error": "The capture could not be analysed. It may be damaged or use an unsupported format."}), 500
    finally:
        if temp_path and os.path.exists(temp_path):
            os.remove(temp_path)


@app.errorhandler(413)
def too_large(_error):
    return jsonify({"error": f"File exceeds the {MAX_UPLOAD_MB} MB upload limit."}), 413


if __name__ == "__main__":
    # Local workshop app only; never expose this development server to a network.
    app.run(host="127.0.0.1", port=5000, debug=False)
